"""sql_write and sql_fix definitions. W: (key, domain, difficulty, spec, reference, ordered)"""

REV = "oi.qty * p.price * (1 - COALESCE(oi.discount, 0))"

W = [
# ---------------- shop
("shop_rev_by_category", "shop", "easy",
 "Total revenue per product category, counting only order lines from orders with status 'paid'. Line revenue = qty * price * (1 - discount), where a NULL discount means no discount. Round revenue to 2 decimals. Return columns: category, revenue.",
 f"SELECT p.category, ROUND(SUM({REV}), 2) AS revenue FROM order_items oi JOIN orders o ON o.id = oi.order_id JOIN products p ON p.id = oi.product_id WHERE o.status = 'paid' GROUP BY p.category", False),
("shop_no_orders", "shop", "easy",
 "List customers who have never placed any order (of any status). Return columns: id, name.",
 "SELECT c.id, c.name FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id)", False),
("shop_status_counts", "shop", "easy",
 "Number of orders per status, most frequent first; break ties by status alphabetically. Return columns: status, n.",
 "SELECT status, COUNT(*) AS n FROM orders GROUP BY status ORDER BY n DESC, status ASC", True),
("shop_country_buyers", "shop", "medium",
 "For every country that has at least one customer: the number of customers and the number of those customers who have at least one 'paid' order. Return columns: country, customers, buyers.",
 "SELECT c.country, COUNT(*) AS customers, SUM(EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id AND o.status = 'paid')) AS buyers FROM customers c GROUP BY c.country", False),
("shop_top3_products", "shop", "medium",
 "The 3 products with the most units sold (sum of qty) across 'paid' orders. Break ties by lower product id. Return columns: id, name, units, ordered by units descending then id ascending.",
 "SELECT p.id, p.name, SUM(oi.qty) AS units FROM order_items oi JOIN orders o ON o.id = oi.order_id JOIN products p ON p.id = oi.product_id WHERE o.status = 'paid' GROUP BY p.id, p.name ORDER BY units DESC, p.id ASC LIMIT 3", True),
("shop_slow_ship", "shop", "medium",
 "Orders that shipped more than 3 days after they were placed (shipped on the 4th day or later). Orders with no ship_date are excluded. Return columns: order_id, days_to_ship (whole days).",
 "SELECT id AS order_id, CAST(julianday(ship_date) - julianday(order_date) AS INTEGER) AS days_to_ship FROM orders WHERE ship_date IS NOT NULL AND julianday(ship_date) - julianday(order_date) > 3", False),
("shop_monthly_rev", "shop", "medium",
 "Monthly revenue from 'paid' orders: month as 'YYYY-MM' of order_date and revenue (qty * price * (1 - discount), NULL discount = 0) rounded to 2 decimals. Only months that have paid orders. Return columns: month, revenue, ordered by month.",
 f"SELECT substr(o.order_date, 1, 7) AS month, ROUND(SUM({REV}), 2) AS revenue FROM order_items oi JOIN orders o ON o.id = oi.order_id JOIN products p ON p.id = oi.product_id WHERE o.status = 'paid' GROUP BY month ORDER BY month", True),
("shop_cumulative_rev", "shop", "hard",
 "Monthly revenue from 'paid' orders (revenue = qty * price * (1 - discount), NULL discount = 0) together with the cumulative revenue up to and including that month. Round both to 2 decimals. Return columns: month ('YYYY-MM'), revenue, cumulative, ordered by month.",
 f"WITH m AS (SELECT substr(o.order_date, 1, 7) AS month, SUM({REV}) AS rev FROM order_items oi JOIN orders o ON o.id = oi.order_id JOIN products p ON p.id = oi.product_id WHERE o.status = 'paid' GROUP BY month) SELECT month, ROUND(rev, 2) AS revenue, ROUND(SUM(rev) OVER (ORDER BY month ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), 2) AS cumulative FROM m ORDER BY month", True),
("shop_first_second_gap", "shop", "hard",
 "For each customer with at least two 'paid' orders, the number of days between their first and second paid order (order by order_date, then id). Return columns: customer_id, gap_days (integer).",
 "WITH r AS (SELECT customer_id, order_date, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY order_date, id) AS rn FROM orders WHERE status = 'paid') SELECT a.customer_id, CAST(julianday(b.order_date) - julianday(a.order_date) AS INTEGER) AS gap_days FROM r a JOIN r b ON b.customer_id = a.customer_id AND a.rn = 1 AND b.rn = 2", False),
("shop_referrers", "shop", "hard",
 "For each customer who referred at least one other customer (referred_by points to them): how many customers they referred and how many of those referred customers have at least one 'paid' order. Return columns: referrer_id, referred, referred_buyers.",
 "SELECT r.id AS referrer_id, COUNT(*) AS referred, SUM(EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id AND o.status = 'paid')) AS referred_buyers FROM customers c JOIN customers r ON r.id = c.referred_by GROUP BY r.id", False),
("shop_unsold_products", "shop", "medium",
 "Products that never appear in any order line of a 'paid' order. Return columns: id, name.",
 "SELECT p.id, p.name FROM products p WHERE NOT EXISTS (SELECT 1 FROM order_items oi JOIN orders o ON o.id = oi.order_id WHERE oi.product_id = p.id AND o.status = 'paid')", False),
("shop_best_product_per_category", "shop", "hard",
 "For each category, the product with the highest revenue from 'paid' orders (revenue = qty * price * (1 - discount), NULL discount = 0); ties go to the lower product id. Categories with no paid sales are omitted. Return columns: category, product_id, revenue (rounded to 2 decimals).",
 f"WITH t AS (SELECT p.category, p.id AS product_id, SUM({REV}) AS rev FROM order_items oi JOIN orders o ON o.id = oi.order_id JOIN products p ON p.id = oi.product_id WHERE o.status = 'paid' GROUP BY p.category, p.id), r AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY category ORDER BY rev DESC, product_id) AS rn FROM t) SELECT category, product_id, ROUND(rev, 2) AS revenue FROM r WHERE rn = 1", False),
("shop_above_avg_customers", "shop", "hard",
 "Order total = sum of qty * price * (1 - discount) over the order's lines (NULL discount = 0). Considering only 'paid' orders, list customers whose average order total is strictly greater than the average order total over all paid orders. Return columns: customer_id, avg_value (rounded to 2 decimals).",
 f"WITH ot AS (SELECT o.id, o.customer_id, SUM({REV}) AS total FROM orders o JOIN order_items oi ON oi.order_id = o.id JOIN products p ON p.id = oi.product_id WHERE o.status = 'paid' GROUP BY o.id, o.customer_id) SELECT customer_id, ROUND(AVG(total), 2) AS avg_value FROM ot GROUP BY customer_id HAVING AVG(total) > (SELECT AVG(total) FROM ot)", False),
("shop_last_order", "shop", "medium",
 "For every customer that has at least one order, their most recent order's date and status (latest order_date; if two orders share the date, the one with the higher id). Return columns: customer_id, last_order_date, last_status.",
 "SELECT customer_id, order_date AS last_order_date, status AS last_status FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY order_date DESC, id DESC) AS rn FROM orders) WHERE rn = 1", False),
# ---------------- hr
("hr_top_level", "hr", "easy",
 "Employees who have no manager. Return columns: id, name.",
 "SELECT id, name FROM employees WHERE manager_id IS NULL", False),
("hr_dept_avg", "hr", "easy",
 "For every department (including departments with no active employees), the number of active employees (term_date IS NULL) and their average salary rounded to 2 decimals, 0 when there are none. Return columns: dept, headcount, avg_salary (dept = department name).",
 "SELECT d.name AS dept, COUNT(e.id) AS headcount, COALESCE(ROUND(AVG(e.salary), 2), 0) AS avg_salary FROM departments d LEFT JOIN employees e ON e.dept_id = d.id AND e.term_date IS NULL GROUP BY d.id, d.name", False),
("hr_above_dept_avg", "hr", "medium",
 "Active employees (term_date IS NULL) whose salary is strictly higher than the average salary of the active employees in their department. Return columns: id, name, salary.",
 "SELECT e.id, e.name, e.salary FROM employees e WHERE e.term_date IS NULL AND e.salary > (SELECT AVG(x.salary) FROM employees x WHERE x.dept_id = e.dept_id AND x.term_date IS NULL)", False),
("hr_second_salary", "hr", "medium",
 "For each department, the second-highest DISTINCT salary among all employees (active or not). Departments with fewer than two distinct salaries are omitted. Return columns: dept_id, salary.",
 "SELECT dept_id, salary FROM (SELECT dept_id, salary, DENSE_RANK() OVER (PARTITION BY dept_id ORDER BY salary DESC) AS r FROM employees) WHERE r = 2 GROUP BY dept_id, salary", False),
("hr_reports_tree", "hr", "hard",
 "All direct and indirect reports of employee 1, with how many levels below employee 1 they are (a direct report is depth 1). Employee 1 itself is not included. Return columns: id, depth.",
 "WITH RECURSIVE t(id, depth) AS (SELECT id, 1 FROM employees WHERE manager_id = 1 UNION ALL SELECT e.id, t.depth + 1 FROM employees e JOIN t ON e.manager_id = t.id) SELECT id, depth FROM t", False),
("hr_root_boss", "hr", "hard",
 "For every employee, the name of the top-level ancestor of their management chain (the person with no manager that they ultimately report to; a top-level employee is their own root). Return columns: id, root_name.",
 "WITH RECURSIVE t(id, root_id) AS (SELECT id, id FROM employees WHERE manager_id IS NULL UNION ALL SELECT e.id, t.root_id FROM employees e JOIN t ON e.manager_id = t.id) SELECT t.id, r.name AS root_name FROM t JOIN employees r ON r.id = t.root_id", False),
("hr_tenure_years", "hr", "medium",
 "For active employees (term_date IS NULL), the number of completed calendar years of service as of 2025-01-01 (an anniversary counts once its month-day is on or before 01-01, i.e. only hire dates on 01-01 earn the current year's anniversary). Return columns: id, years.",
 "SELECT id, CAST(strftime('%Y', '2025-01-01') AS INTEGER) - CAST(strftime('%Y', hire_date) AS INTEGER) - (strftime('%m-%d', '2025-01-01') < strftime('%m-%d', hire_date)) AS years FROM employees WHERE term_date IS NULL", False),
("hr_over_budget", "hr", "hard",
 "Departments whose total salary of active employees (term_date IS NULL) exceeds the department budget. Return columns: name, total, budget, over_by (total minus budget).",
 "SELECT d.name, SUM(e.salary) AS total, d.budget, SUM(e.salary) - d.budget AS over_by FROM departments d JOIN employees e ON e.dept_id = d.id WHERE e.term_date IS NULL GROUP BY d.id, d.name, d.budget HAVING SUM(e.salary) > d.budget", False),
("hr_no_bonus_2024", "hr", "medium",
 "Employees (any status) who have no 2024 bonus: either there is no bonuses row for year 2024, or that row's amount is NULL. Return columns: id, name.",
 "SELECT e.id, e.name FROM employees e WHERE NOT EXISTS (SELECT 1 FROM bonuses b WHERE b.emp_id = e.id AND b.year = 2024 AND b.amount IS NOT NULL)", False),
("hr_quartiles", "hr", "hard",
 "Split all employees into 4 quartiles by salary using NTILE(4), highest salary first (ties broken by lower id first) so quartile 1 holds the best paid. Return columns: id, quartile.",
 "SELECT id, NTILE(4) OVER (ORDER BY salary DESC, id ASC) AS quartile FROM employees", False),
# ---------------- events
("ev_buyers", "events", "easy",
 "How many distinct users have at least one 'purchase' event? Return a single column: buyers.",
 "SELECT COUNT(DISTINCT user_id) AS buyers FROM events WHERE kind = 'purchase'", False),
("ev_dau", "events", "medium",
 "Daily active users: for each calendar day (the date part of ts) the number of distinct users with any event. Return columns: day, dau, ordered by day.",
 "SELECT date(ts) AS day, COUNT(DISTINCT user_id) AS dau FROM events GROUP BY day ORDER BY day", True),
("ev_sessions", "events", "hard",
 "Sessionize each user's events: order a user's events by ts (then id); a new session starts at the first event and whenever the gap to the user's previous event is strictly more than 30 minutes. Return the number of sessions per user. Return columns: user_id, sessions.",
 "WITH g AS (SELECT user_id, CASE WHEN LAG(ts) OVER (PARTITION BY user_id ORDER BY ts, id) IS NULL OR (julianday(ts) - julianday(LAG(ts) OVER (PARTITION BY user_id ORDER BY ts, id))) * 1440 > 30 THEN 1 ELSE 0 END AS s FROM events) SELECT user_id, SUM(s) AS sessions FROM g GROUP BY user_id", False),
("ev_funnel", "events", "hard",
 "Funnel over each user's FIRST event of each kind: viewed = users with a 'view' event; clicked_after_view = those whose first 'click' is later than their first 'view'; purchased_after_click = those among them whose first 'purchase' is later than their first 'click'. Return one row with columns: viewed, clicked_after_view, purchased_after_click.",
 "WITH f AS (SELECT user_id, MIN(CASE WHEN kind = 'view' THEN ts END) AS v, MIN(CASE WHEN kind = 'click' THEN ts END) AS c, MIN(CASE WHEN kind = 'purchase' THEN ts END) AS p FROM events GROUP BY user_id) SELECT COUNT(v) AS viewed, COALESCE(SUM(c > v), 0) AS clicked_after_view, COALESCE(SUM(c > v AND p > c), 0) AS purchased_after_click FROM f", False),
("ev_revenue_by_plan", "events", "medium",
 "Revenue per plan: sum of the amount of 'purchase' events of users on that plan, counting NULL amounts as 0. Plans whose users made no purchases must still appear with 0. Return columns: plan, revenue.",
 "SELECT u.plan, COALESCE(SUM(e.amount), 0) AS revenue FROM users u LEFT JOIN events e ON e.user_id = u.id AND e.kind = 'purchase' GROUP BY u.plan", False),
("ev_signup_only", "events", "medium",
 "Users who have a 'signup' event and no event of any other kind. Return a single column: user_id.",
 "SELECT user_id FROM events GROUP BY user_id HAVING SUM(kind = 'signup') > 0 AND SUM(kind <> 'signup') = 0", False),
("ev_moving_avg", "events", "hard",
 "Daily purchase totals (sum of amount of 'purchase' events by date(ts), NULL amounts ignored; days without any non-NULL amount are omitted) and the average of the current and up to two preceding listed days (ROWS frame, not calendar days), rounded to 2 decimals. Return columns: day, total, moving_avg, ordered by day.",
 "WITH d AS (SELECT date(ts) AS day, SUM(amount) AS total FROM events WHERE kind = 'purchase' AND amount IS NOT NULL GROUP BY day) SELECT day, total, ROUND(AVG(total) OVER (ORDER BY day ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 2) AS moving_avg FROM d ORDER BY day", True),
("ev_page_before_purchase", "events", "hard",
 "For each user with a 'purchase' event, find the page of their last 'view' event strictly before their first purchase (latest ts, ties by higher event id). Users with no such view are omitted. Return columns: user_id, page.",
 "WITH fp AS (SELECT user_id, MIN(ts) AS pts FROM events WHERE kind = 'purchase' GROUP BY user_id), v AS (SELECT e.user_id, e.page, ROW_NUMBER() OVER (PARTITION BY e.user_id ORDER BY e.ts DESC, e.id DESC) AS rn FROM events e JOIN fp ON fp.user_id = e.user_id WHERE e.kind = 'view' AND e.ts < fp.pts) SELECT user_id, page FROM v WHERE rn = 1", False),
# ---------------- library
("lib_genre_recent", "library", "easy",
 "Number of books published after the year 2000 per genre, most first (ties by genre alphabetically). Return columns: genre, n.",
 "SELECT genre, COUNT(*) AS n FROM books WHERE year > 2000 GROUP BY genre ORDER BY n DESC, genre ASC", True),
("lib_overdue", "library", "medium",
 "As of 2024-06-30, loans that are or were late: days_late = (returned_on if returned, otherwise 2024-06-30) minus due_on, in whole days. Return only loans with days_late > 0. Return columns: loan_id, days_late.",
 "SELECT id AS loan_id, CAST(julianday(COALESCE(returned_on, '2024-06-30')) - julianday(due_on) AS INTEGER) AS days_late FROM loans WHERE julianday(COALESCE(returned_on, '2024-06-30')) - julianday(due_on) > 0", False),
("lib_genre_variety", "library", "medium",
 "Members who have borrowed books from at least 3 distinct genres, with that number of genres. Return columns: member_id, genres.",
 "SELECT l.member_id, COUNT(DISTINCT b.genre) AS genres FROM loans l JOIN books b ON b.id = l.book_id GROUP BY l.member_id HAVING COUNT(DISTINCT b.genre) >= 3", False),
("lib_all_books_loaned", "library", "hard",
 "Authors who have at least one book and for whom every one of their books has been loaned at least once. Return columns: author_id, name.",
 "SELECT a.id AS author_id, a.name FROM authors a WHERE EXISTS (SELECT 1 FROM books b WHERE b.author_id = a.id) AND NOT EXISTS (SELECT 1 FROM books b WHERE b.author_id = a.id AND NOT EXISTS (SELECT 1 FROM loans l WHERE l.book_id = b.id))", False),
("lib_avg_duration", "library", "medium",
 "Average loan duration in days (returned_on minus loaned_on) per book genre, over returned loans only, rounded to 1 decimal. Genres without returned loans are omitted. Return columns: genre, avg_days.",
 "SELECT b.genre, ROUND(AVG(julianday(l.returned_on) - julianday(l.loaned_on)), 1) AS avg_days FROM loans l JOIN books b ON b.id = l.book_id WHERE l.returned_on IS NOT NULL GROUP BY b.genre", False),
("lib_never_loaned", "library", "medium",
 "Books that were never loaned, with their author's name. Return columns: id, title, author, ordered by id.",
 "SELECT b.id, b.title, a.name AS author FROM books b JOIN authors a ON a.id = b.author_id WHERE NOT EXISTS (SELECT 1 FROM loans l WHERE l.book_id = b.id) ORDER BY b.id", True),
("lib_top_borrower_per_book", "library", "hard",
 "For each book that has been loaned, the member who borrowed it most often (ties go to the lower member id) and how many times. Return columns: book_id, member_id, times.",
 "WITH c AS (SELECT book_id, member_id, COUNT(*) AS times FROM loans GROUP BY book_id, member_id), r AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY book_id ORDER BY times DESC, member_id) AS rn FROM c) SELECT book_id, member_id, times FROM r WHERE rn = 1", False),
("lib_shared_books", "library", "hard",
 "Pairs of members (m1 < m2) who have both borrowed at least 2 of the same books (count each book once per pair). Return columns: m1, m2, shared.",
 "WITH mb AS (SELECT DISTINCT member_id, book_id FROM loans) SELECT a.member_id AS m1, b.member_id AS m2, COUNT(*) AS shared FROM mb a JOIN mb b ON a.book_id = b.book_id AND a.member_id < b.member_id GROUP BY a.member_id, b.member_id HAVING COUNT(*) >= 2", False),
# ---------------- sensors
("sen_stats", "sensors", "easy",
 "Per sensor, the minimum, maximum and average reading, ignoring NULL values; average rounded to 2 decimals. Sensors with no readings at all are omitted; a sensor whose readings are all NULL yields NULLs. Return columns: sensor_id, mn, mx, av.",
 "SELECT sensor_id, MIN(value) AS mn, MAX(value) AS mx, ROUND(AVG(value), 2) AS av FROM readings GROUP BY sensor_id", False),
("sen_missing_by_site", "sensors", "medium",
 "For each site, the number of readings whose value is NULL (0 if none; sites with no readings at all still appear with 0). Return columns: site, missing.",
 "SELECT s.site, COUNT(r.sensor_id) - COUNT(r.value) AS missing FROM sensors s LEFT JOIN readings r ON r.sensor_id = s.id GROUP BY s.site", False),
("sen_gaps", "sensors", "hard",
 "Find reporting gaps: consecutive readings (in ts order, per sensor, regardless of NULL values) that are MORE than 90 minutes apart. Return columns: sensor_id, gap_start (ts of the earlier reading), gap_end (ts of the later reading).",
 "WITH x AS (SELECT sensor_id, LAG(ts) OVER (PARTITION BY sensor_id ORDER BY ts) AS gap_start, ts AS gap_end FROM readings) SELECT sensor_id, gap_start, gap_end FROM x WHERE gap_start IS NOT NULL AND (julianday(gap_end) - julianday(gap_start)) * 1440 > 90", False),
("sen_forward_fill", "sensors", "hard",
 "For every reading row, return a filled value: the reading's own value if not NULL, otherwise the most recent earlier non-NULL value of the same sensor (NULL if there is none). Return columns: sensor_id, ts, filled.",
 "SELECT r.sensor_id, r.ts, (SELECT r2.value FROM readings r2 WHERE r2.sensor_id = r.sensor_id AND r2.ts <= r.ts AND r2.value IS NOT NULL ORDER BY r2.ts DESC LIMIT 1) AS filled FROM readings r", False),
("sen_latest_hot", "sensors", "medium",
 "Using each sensor's most recent non-NULL reading, list the sensors where that reading is greater than 30. Return columns: sensor_id, ts, value.",
 "SELECT sensor_id, ts, value FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY sensor_id ORDER BY ts DESC) AS rn FROM readings WHERE value IS NOT NULL) WHERE rn = 1 AND value > 30", False),
("sen_hour_profile", "sensors", "medium",
 "Average value by sensor and hour of day (two-digit string from ts, e.g. '07'), ignoring NULL values, rounded to 2 decimals; groups with only NULL values are omitted. Return columns: sensor_id, hour, avg_value.",
 "SELECT sensor_id, strftime('%H', ts) AS hour, ROUND(AVG(value), 2) AS avg_value FROM readings WHERE value IS NOT NULL GROUP BY sensor_id, hour", False),
("sen_spikes", "sensors", "hard",
 "Spikes: a reading where the value is more than 5 higher than the immediately preceding reading of the same sensor (preceding by ts). Both values must be non-NULL (a NULL previous reading means no comparison). Return columns: sensor_id, ts, delta (value minus previous value).",
 "WITH x AS (SELECT sensor_id, ts, value, LAG(value) OVER (PARTITION BY sensor_id ORDER BY ts) AS prev FROM readings) SELECT sensor_id, ts, value - prev AS delta FROM x WHERE value IS NOT NULL AND prev IS NOT NULL AND value - prev > 5", False),
# ---------------- school
("sch_gpa", "school", "medium",
 "Credit-weighted GPA per student: sum(grade * credits) / sum(credits) over enrollments that have a grade (NULL grades ignored entirely). Students with no graded enrollment are omitted. Round to 2 decimals. Return columns: student_id, gpa.",
 "SELECT e.student_id, ROUND(SUM(e.grade * c.credits) * 1.0 / SUM(c.credits), 2) AS gpa FROM enrollments e JOIN courses c ON c.id = e.course_id WHERE e.grade IS NOT NULL GROUP BY e.student_id", False),
("sch_pivot_terms", "school", "medium",
 "For every course (including courses with no enrollments) the number of enrollments in each term. Return columns: course_id, f23, s24, f24.",
 "SELECT c.id AS course_id, COALESCE(SUM(e.term = 'F23'), 0) AS f23, COALESCE(SUM(e.term = 'S24'), 0) AS s24, COALESCE(SUM(e.term = 'F24'), 0) AS f24 FROM courses c LEFT JOIN enrollments e ON e.course_id = c.id GROUP BY c.id", False),
("sch_best_course", "school", "medium",
 "For each student with at least one graded enrollment, their best graded enrollment: highest grade; ties go to the lower course id, then the earlier term string in alphabetical order. Return columns: student_id, course_id, grade.",
 "SELECT student_id, course_id, grade FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY student_id ORDER BY grade DESC, course_id, term) AS rn FROM enrollments WHERE grade IS NOT NULL) WHERE rn = 1", False),
("sch_above_course_avg", "school", "medium",
 "Enrollments whose grade is strictly above the average grade of that course (over all terms, NULL grades ignored). Return columns: course_id, student_id, term, grade.",
 "SELECT e.course_id, e.student_id, e.term, e.grade FROM enrollments e WHERE e.grade > (SELECT AVG(x.grade) FROM enrollments x WHERE x.course_id = e.course_id)", False),
("sch_students_per_year", "school", "easy",
 "Number of students per year of study, ordered by year ascending. Return columns: year, students.",
 "SELECT year, COUNT(*) AS students FROM students GROUP BY year ORDER BY year", True),
("sch_all_math", "school", "hard",
 "Students who have an enrollment (any term, graded or not) in every MATH course. Assume there is at least one MATH course. Return columns: student_id.",
 "SELECT s.id AS student_id FROM students s WHERE NOT EXISTS (SELECT 1 FROM courses c WHERE c.dept = 'MATH' AND NOT EXISTS (SELECT 1 FROM enrollments e WHERE e.student_id = s.id AND e.course_id = c.id))", False),
]

